export const BG_LAYERS = [{"target": "floor", "css": "background-image: repeating-linear-gradient(90deg, rgba(74,48,18,0.07) 0 130px, rgba(255,242,205,0.05) 130px 260px, transparent 260px 390px, rgba(58,38,14,0.06) 390px 520px)", "comment": "地板·板块色差条 — 叠在现有【竖向板缝(每130px)】那层之上，再加一层独立 div。以 130px 为一整板宽，每隔几板循环一次「略浅/中性/略深」整板色调，模拟旧木地板不同批次的板子。pitch 与现有竖缝(90deg ... 2px 130px)对齐，色差正好落在两条缝之间一整板。class 用 absolute inset-x-0 bottom-0 top-[30%] pointer-events-none，mixBlendMode 可选 'soft-light' 让色差更含蓄。"}, {"target": "floor", "css": "background-image: radial-gradient(circle at 18% 22%, rgba(74,48,18,0.34) 0 1.4px, transparent 2.2px), radial-gradient(circle at 62% 58%, rgba(74,48,18,0.30) 0 1.6px, transparent 2.4px), radial-gradient(circle at 88% 84%, rgba(58,38,14,0.32) 0 1.3px, transparent 2px); background-size: 260px 188px, 330px 224px, 410px 196px", "comment": "地板·节疤点 — 稀疏的木节(knot)小黑点，三组不同 background-size 让它们以不同稀疏间距平铺、互不重合，看起来是随机散落而非网格。叠在板块色差条之上、家具/角色 z 之下。size 全是质数感的非整数倍数，避免和 130/32 的板缝对齐成规则点阵。点很小(1.3~1.6px)且半透明，远看像旧地板上的节疤。"}, {"target": "wall", "css": "background: linear-gradient(180deg, #e3d2ad 0%, #dccaa0 46%, #d2bc90 46.001%, #c9b07f 100%)", "comment": "墙面·墙纸上半/下半双色 — 替换现有墙体 base 渐变(原 #ddc9a2→#d2bc90)。在 46% 处做一道硬色阶:上半略亮暖(浅米黄墙纸)、下半略深(护墙以上的墙面被家具/光线压暗)，46% 大约落在 picture-rail 下方一点、wainscot(22%) 之上，形成上浅下深的双色墙纸。仍是 top-0 h-[30%] 那层。"}, {"target": "wall", "css": "background-image: linear-gradient(180deg, rgba(120,92,50,0.55) 0 1px, rgba(255,244,214,0.6) 1px 2px, rgba(120,92,50,0.30) 2px 3px, transparent 3px); background-position: 0 18%; background-size: 100% 100%; background-repeat: no-repeat", "comment": "墙面·picture-rail 挂画线 — 一条贴在墙上 18% 高度的横向挂画线(暗木+上沿高光+下沿阴影三像素带)。新加一层 absolute inset-x-0 top-0 h-[30%] pointer-events-none。18% 正好在 wainscot 顶(22%)之上、画框(7~8%)之下，挂画线在视觉上「挂着」上方那两幅画。若想更立体可在 div 上再加 boxShadow:'0 1px 0 rgba(255,244,214,0.4)'。"}, {"target": "skirting", "css": "background: linear-gradient(180deg, #a37b42 0%, #8a6534 40%, #6f4f28 100%); box-shadow: inset 0 1px 0 rgba(255,244,214,0.7), 0 1px 1px rgba(40,26,10,0.35)", "comment": "踢脚线·加高光 — 替换现有那条扁平的 #8a6534 skirting(top:30% height:6px)。改成上亮下暗的三段竖向渐变模拟圆角踢脚线，inset 顶部高光(0 1px)是打在踢脚线上沿的反光，外阴影(0 1px 1px)让它从地板上微微凸起。建议把那条 div 的 height 从 6px 提到 7~8px 让高光有地方落。"}, {"target": "new-layer", "css": "background-image: repeating-linear-gradient(90deg, transparent 0 128px, rgba(40,26,10,0.10) 128px 130px, rgba(255,242,205,0.07) 130px 132px, transparent 132px 130px)", "comment": "地板·板缝倒角强化(可选第6条) — 单独一层叠在最上，给每道竖板缝(130px)补一对「暗缝+亮棱」双线,让旧木板的接缝更有立体倒角感、配合上面的板块色差条更耐看。与现有竖缝(2px 130px)同 pitch 对齐。同样 absolute inset-x-0 bottom-0 top-[30%] pointer-events-none，放在角色 z 之下。"}];

